import React, { useCallback, useEffect, useState } from 'react'
import { Row, Divider, Input, Spin, notification } from 'antd'
import { connect } from "react-redux"

import { GuidelineStyle } from './index.style'
import ShowPdf from './viewPdf/index.js'
import guidelineActions from '../../../redux/guideline/action'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'

const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

const { getGuidelineList } = guidelineActions

const Search = Input.Search

const Guideline = ({
  getGuidelineList,
  guidelineListLoading,
  guidelineListError,
  guidelineList,
  resetLoadingRedux,
  resetErrorRedux
}) => {
  const [guidelineFilteredFiles, setGuidelineFilteredFiles] = useState([])

  useEffect(() => {
      getGuidelineList()
  }, [])

  useEffect(() => {
    if(guidelineListError && !guidelineListLoading){
      notification.error({message: "Error while fetching list"})
      resetLoadingRedux(['GET_GUIDELINE_LIST'])
      resetErrorRedux(['GET_GUIDELINE_LIST'])
    }
  }, [guidelineListError, guidelineListLoading])

  useEffect(() => {
    setGuidelineFilteredFiles(guidelineList)
  }, [guidelineList])

  const submitSearch = useCallback((text) => {
    const filteredFiles = guidelineList.filter((file) => file.file_name.toLocaleLowerCase().includes(text.toLocaleLowerCase()))
    
    if(filteredFiles.length !== guidelineFilteredFiles.length){
      setGuidelineFilteredFiles(filteredFiles)
    } 
  }, [guidelineList, guidelineFilteredFiles])
  
  return (
    <GuidelineStyle>
      <Row justify='space-between' align='middle'>
        <label>
          <b>Guideline List</b>
        </label>
        
        <Search
          placeholder='Search Guideline'
          allowClear
          onSearch={submitSearch}
          className='search'
        />
      </Row>
      <Divider />
      <Spin spinning={!!guidelineListLoading}>
        <div className='files-wrapper'>
          {
            guidelineFilteredFiles.length > 0 ? guidelineFilteredFiles.map((file, index) => {
              return <ShowPdf key={index} file={file} />
            }) : "No Guideline Found"
          }
        </div>
      </Spin>
    </GuidelineStyle>
  )
}

export default connect(
  (state) => ({
    guidelineListLoading: state.Loading.GET_GUIDELINE_LIST,
    guidelineListError: state.Error.GET_GUIDELINE_LIST,
    guidelineList: state.Guideline.guidelineList
  }),
  {
    getGuidelineList,
    resetLoadingRedux,
    resetErrorRedux
  }
)(Guideline)
