import {Document, Page, pdfjs} from "react-pdf"
import fileDownload from "js-file-download"

import {PdfBoxStyle} from "./index.style"
import downloadIcon from "../../../../../constants/icons/download.svg"
import {useEffect, useState} from "react"

pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.js`

function getFileSize(bytes = 0) {
  let fileSize = (bytes / 1073741824).toFixed(1) + " GB"
  if(bytes < 1024) {
    fileSize = bytes + " Bytes"
  } else if(bytes < 1048576) {
    fileSize = (bytes / 1024).toFixed(1) + " KB"
  } else if(bytes < 1073741824) {
    fileSize = (bytes / 1048576).toFixed(1) + " MB"
  } 
  return fileSize
}

const PdfComponent = ({file}) => {
  const [blobFile, setBlobFile] = useState()

  useEffect(() => {
    fetch(file.file_url, {
      method: "GET",
      headers: {
        "Content-Type": "application/pdf"
      }
    })
      .then((response) => response.blob())
      .then((blob) => {
        setBlobFile(blob)
      })
  }, [])

  const downloadPdf = (e) => {
    e.stopPropagation()
    blobFile && fileDownload(blobFile, file.file_name)
  }
  const parent = () => {
    window.open(file.file_url, "_blank")
  }
  return (
    <PdfBoxStyle onClick={parent}>
      <Document file={{url: file.file_url}}>
        <Page
          pageNumber={1}
          className="document-card-item-pdf"
          renderTextLayer={false}
        />
      </Document>
      <div className="bottom">
        <div className="pdf-data">
          <span className="pdf-name">{file.file_name}</span>
          <span className="pdf-size">{getFileSize(blobFile?.size)}</span>
        </div>
        <span onClick={downloadPdf}>
          <img src={downloadIcon} alt="img" />
        </span>
      </div>
    </PdfBoxStyle>
  )
}

export default PdfComponent
